<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';import {useRoute} from 'vue-router';import {useCoffee} from '../stores/coffee';import Icon from './Icon.vue';import {connectionLabel} from '../../../../packages/shared/src/domain';
const route=useRoute();const s=useCoffee();const expanded=ref(false);
const main=[{path:'/pos',label:'Bán hàng',icon:'cart'},{path:'/tables',label:'Bàn & khu vực',icon:'table'},{path:'/orders',label:'Đơn hàng',icon:'orders'},{path:'/kitchen',label:'Quầy pha chế',icon:'kitchen'},{path:'/waiter',label:'Phục vụ',icon:'mobile'}];
const admin=[{path:'/admin/dashboard',label:'Tổng quan',icon:'dashboard'},{path:'/admin/receipts',label:'Bill đã xuất',icon:'receipt'},{path:'/admin/products',label:'Thực đơn',icon:'coffee'},{path:'/admin/images',label:'Hình ảnh',icon:'image'},{path:'/admin/categories',label:'Danh mục',icon:'layers'},{path:'/admin/banks',label:'Ngân hàng',icon:'bank'},{path:'/admin/branches',label:'Cơ sở',icon:'store'},{path:'/admin/printers',label:'Máy in',icon:'printer'},{path:'/admin/staff',label:'Nhân viên',icon:'staff'},{path:'/admin/permissions',label:'Phân quyền',icon:'shield'},{path:'/admin/reports',label:'Báo cáo',icon:'reports'},{path:'/admin/invoices',label:'Hóa đơn điện tử',icon:'file'},{path:'/admin/subscription',label:'Gói dịch vụ',icon:'package'},{path:'/admin/audit',label:'Nhật ký',icon:'orders'},{path:'/admin/settings',label:'Cài đặt',icon:'settings'}];
const adminSection=computed(()=>route.path.startsWith('/admin'));
const online=ref(navigator.onLine);const updateOnline=()=>online.value=navigator.onLine;onMounted(()=>{window.addEventListener('online',updateOnline);window.addEventListener('offline',updateOnline)});onUnmounted(()=>{window.removeEventListener('online',updateOnline);window.removeEventListener('offline',updateOnline)});const activeLink=(path:string)=>route.path===path;
function navigate(){expanded.value=false}
</script>
<template><div class="app-shell" :class="{'is-admin':adminSection}"><div v-if="expanded" class="sidebar-scrim" @click="expanded=false"></div><aside class="sidebar" :class="{open:expanded}"><RouterLink class="brand" to="/pos" @click="navigate"><span class="brand-mark"><Icon name="coffee" :size="26"/></span><span>Coffee <b>POS</b><small>Vận hành quán mỗi ngày</small></span></RouterLink><nav aria-label="Điều hướng chính"><template v-if="!adminSection"><RouterLink v-for="item in main" :key="item.path" :to="item.path" :class="{active:activeLink(item.path)}" @click="navigate"><Icon :name="item.icon"/><span>{{item.label}}</span><span v-if="item.path==='/orders'" class="nav-count">{{s.orders.filter(o=>o.state==='pending').length}}</span></RouterLink><div class="nav-divider"></div><RouterLink to="/admin/dashboard" @click="navigate"><Icon name="dashboard"/><span>Admin</span><Icon name="next" :size="16"/></RouterLink><RouterLink to="/admin/products" @click="navigate"><Icon name="coffee"/><span>Thực đơn</span></RouterLink><RouterLink to="/admin/reports" @click="navigate"><Icon name="reports"/><span>Báo cáo</span></RouterLink><RouterLink to="/admin/settings" @click="navigate"><Icon name="settings"/><span>Cài đặt</span></RouterLink></template><template v-else><RouterLink to="/pos" @click="navigate"><Icon name="back"/><span>Về bán hàng</span></RouterLink><div class="nav-divider"></div><RouterLink v-for="item in admin" :key="item.path" :to="item.path" :class="{active:activeLink(item.path)}" @click="navigate"><Icon :name="item.icon"/><span>{{item.label}}</span></RouterLink></template></nav><div class="sidebar-bottom"><RouterLink to="/platform" @click="navigate"><Icon name="globe" :size="18"/>Quản trị SaaS</RouterLink><small>Quản lý rõ ràng. Bán hàng nhẹ nhàng.</small></div></aside><div class="shell-main"><header class="topbar"><div class="topbar-title"><button class="icon-button mobile-toggle" aria-label="Mở điều hướng" @click="expanded=!expanded"><Icon name="menu"/></button><h1>{{route.meta.title}}</h1><span v-if="route.path==='/pos'" class="eyebrow-badge">Tại quầy</span></div><div class="topbar-actions"><label class="branch-select"><Icon name="store"/><select aria-label="Cơ sở đang xem" :value="s.branchId" @change="s.changeBranch(($event.target as HTMLSelectElement).value)"><option v-for="b in s.state.branches.filter(b=>b.active)" :value="b.id" :key="b.id">Chi nhánh {{b.name}}</option></select><Icon name="down" :size="14"/></label><span class="connection"><i :class="{disconnected:!online}"></i>{{connectionLabel(online)}}</span><label class="role-select"><span class="avatar">MA</span><select aria-label="Vai trò xem" v-model="s.role"><option v-for="(name,key) in s.roleLabels" :value="key" :key="key">{{name}}</option></select></label></div></header><main id="main-content"><slot/></main></div></div></template>
